arguments.command:
# Check for existing skills directories in the workspace and user home
$locations = @(
  "$env:USERPROFILE\.copilot\skills",
  "$env:USERPROFILE\.vscode\extensions",
  "$PWD\.copilot\skills"
)

foreach ($location in $locations) {
  Write-Host "Checking: $location"
  if (Test-Path $location) {
    Write-Host "✓ Exists"
    Get-ChildItem $location -Force | Select-Object Name, FullName
  } else {
    Write-Host "✗ Does not exist"
  }
  Write-Host ""
}

